/* Includes the device wrapper itself, so the hack's own pixel packing runs
 * through whatever adapters the wrapper sets up. The renamed entry keeps it
 * from clashing with the copy in the registry. */
#define binaryhorizon_hack binaryhorizon_hack_under_test
#include "hacks/binaryhorizon_swapped.c"

static Canvas cv;
static Display *dpy;

void setUp(void) {
  TEST_ASSERT_EQUAL_INT(0, canvas_init(&cv, 64, 64, malloc));
  dpy = xshim_open_display(&cv);
}
void tearDown(void) {
  xshim_close_display(dpy);
  canvas_free(&cv);
}

/* The hack packs and unpacks ordinary RGB565 itself, but images hold
 * canvas-order (byte-swapped) pixels. Pure red is 0xF800. */
void test_a_blended_point_reaches_the_image_in_canvas_order(void) {
  struct state *st = binaryhorizon_init(dpy, 1);
  draw_point(st, 2, 3, rgb2point(16, 255, 0, 0), 1.0f);
  TEST_ASSERT_EQUAL_HEX64(px_swap(0xF800), XGetPixel(st->buf, 2, 3));
  TEST_ASSERT_EQUAL_HEX64(0, XGetPixel(st->buf, 3, 3));
  binaryhorizon_free(dpy, 1, st);
}

/* A 16-bit image copies to the canvas a row at a time. */
void test_the_image_is_sixteen_bits_a_pixel(void) {
  struct state *st = binaryhorizon_init(dpy, 1);
  TEST_ASSERT_EQUAL_INT(16, st->buf->bits_per_pixel);
  TEST_ASSERT_EQUAL_INT(64, st->buf->width);
  TEST_ASSERT_EQUAL_INT(64, st->buf->height);
  binaryhorizon_free(dpy, 1, st);
}

/* Every `duration` seconds the hack starts again and allocates a new pixel
 * buffer without freeing the old one: 868 KB each time on the device. */
void test_a_timed_restart_does_not_leak_the_pixel_buffer(void) {
  struct state *st = binaryhorizon_init(dpy, 1);
  st->duration = 30;
  binaryhorizon_draw(dpy, 1, st);
  const size_t before = __sanitizer_get_current_allocated_bytes();
  for (int i = 0; i < 20; i++) {
    st->start_time = 0;
    binaryhorizon_draw(dpy, 1, st);
  }
  const size_t after = __sanitizer_get_current_allocated_bytes();
  TEST_ASSERT_TRUE(after <= before + 512);
  binaryhorizon_free(dpy, 1, st);
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_a_blended_point_reaches_the_image_in_canvas_order);
  RUN_TEST(test_the_image_is_sixteen_bits_a_pixel);
  RUN_TEST(test_a_timed_restart_does_not_leak_the_pixel_buffer);
  return UNITY_END();
}

/* Builds the unmodified binaryhorizon.c for the canvas's pixel order and frees
 * what it leaks on its timed restart.
 *
 * The hack packs and unpacks ordinary RGB565 itself (point2rgb, rgb2point),
 * but images hold canvas-order, byte-swapped pixels, so XPutPixel swaps. Its
 * XGetImage of a black pixmap is a 16-bit image of zeros, which XPutImage
 * copies a row at a time; the shim's XGetImage makes a 32-bit one that
 * XPutImage copies a pixel at a time.
 *
 * Every `duration` seconds the hack calls create_buffers again, which
 * callocs a new pixel buffer and never frees the old one (868 KB on the
 * device). The wrapper frees it when the same condition holds. */
#include <stdlib.h>
#include <string.h>

#include "screenhack.h"

#include "core/canvas.h"

#define XPutPixel(im, x, y, c) XPutPixel(im, x, y, px_swap((uint16_t)(c)))

static XImage *binaryhorizon_black_image(Display *dpy, Drawable d, int x, int y,
                                         unsigned int w, unsigned int h,
                                         unsigned long plane_mask, int format) {
  (void)d, (void)x, (void)y, (void)plane_mask, (void)format;
  XImage *im = XCreateImage(dpy, NULL, 16, ZPixmap, 0, NULL, w, h, 32, 0);
  if (im) im->data = (char *)calloc(h, (size_t)im->bytes_per_line);
  return im;
}
#define XGetImage binaryhorizon_black_image

