import re
import sys

IDLE = 6989667
want = [
    "Marbling", "Deco", "IMSMap", "MetaBalls", "Munch", "CCurve",
    "BinaryHorizon", "RotZoomer", "Twang", "NerveRot", "Flow", "Bouboule",
    "Ant", "HyperBall", "Demon", "Droste", "Polyominoes", "Barcode",
]
rows = {}
for line in open(sys.argv[1], errors="replace"):
    m = re.match(
        r"run (\S+) fps=([\d.]+) step=([\d.]+)ms push=([\d.]+)ms sync=\S+ wait=([\d.]+)ms rows=(\d+) heap=(\d+) psram=(\d+)",
        line,
    )
    if m and m.group(1) in want:
        rows.setdefault(m.group(1), []).append([float(x) for x in m.groups()[1:]])


def rng(vals, unit="", digits=1):
    lo, hi = min(vals), max(vals)
    f = f"{{:.{digits}f}}"
    if round(lo, digits) == round(hi, digits):
        return f.format(lo) + unit
    return f.format(lo) + "-" + f.format(hi) + unit


for n in want:
    r = rows[n][1:] or rows[n]  # push= is read from the second window on
    fps = [x[0] for x in r]
    step = [x[1] for x in r]
    push = [x[2] for x in r]
    wait = [x[3] for x in r]
    extra = IDLE - min(x[7] for x in rows[n])
    if extra < 20000:
        mem = "none measurable"
    elif extra < 900000:
        mem = f"about {round(extra / 1024 / 10) * 10} KB"
    else:
        mem = f"about {extra / 1048576:.1f} MB"
    print(
        f"| {n} | {rng(fps)} | {rng(step, ' ms')} | {rng(push, ' ms')} | "
        f"{rng(wait, ' ms')} | {mem} |"
    )

